describe('User Logout Functionality', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('securepassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.wait('@loginRequest');
    cy.get('[data-testid="user-profile"]').should('be.visible');
  });

  it('should log out user and clear session', () => {
    cy.get('[data-testid="logout-button"]').click();
    cy.intercept('POST', '/api/auth/logout').as('logoutRequest');
    cy.wait('@logoutRequest');

    cy.url().should('include', '/login');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('have.value', '');
    cy.get('[data-testid="user-profile"]').should('not.exist');
  });

  it('should handle logout with active session', () => {
    cy.get('[data-testid="logout-button"]').click();
    cy.intercept('POST', '/api/auth/logout').as('logoutRequest');
    cy.wait('@logoutRequest');

    cy.url().should('include', '/login');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('have.value', '');

    // Verify session token is cleared
    cy.get('[data-testid="session-token"]').should('not.exist');

    // Verify user is redirected to login page
    cy.url().should('include', '/login');
  });
});
